   */
  public void setInput(String input) {
    this.input = input.toLowerCase(); // convert all characters to lowercase for case-insensitive matching
  }

  /**
   * Retrieves the input string for the VowelCounter object
   * 
   * @return the user input string
   */
  public String getInput() {
    return input;
  }

  /**
   * Counts the number of vowels in the input string
   * 
   * @return the count of vowels in the input string
   */
  public int countVowels() {
    int count = 0;

    for (int I = 0; I < input.length(); i++) {
      char c = input.charAt(i);

      if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
        count++;
      }
    }

    return count;
  }

  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    VowelCounter counter = new VowelCounter();

    System.out.print("Enter a string: ");
    counter.setInput(scanner.nextLine());

    int numVowels = counter.countVowels();
    System.out.println("Number of vowels: " + numVowels);
  }
}
