```
def sauteOrPanFry(text:String):String = {
val sauteKeywords = Set("sauté","stir-fry","toss")
val panFryKeywords = Set("pan-fry","fry")
val commonKeywords = sauteKeywords.intersect(panFryKeywords)
val sauteOnlyKeywords = sauteKeywords.diff(commonKeywords)
val panFryOnlyKeywords = panFryKeywords.diff(commonKeywords)
val containsSaute = sauteKeywords.exists(text.contains)
val containsPanFry = panFryKeywords.exists(text.contains)
if (containsSaute && !containsPanFry) {
s"$text はサテーリングを記述します。ソースとパンフライの間の類似点は、両方の技法は油でホットパンで食べ物を調理することである。違いは、サテーリングは通常、高い熱で小さな食物を素早く調理する必要があり、パンフライは、長い期間中熱で大きな食物を調理する必要があるということです。
} else if (containsPanFry && !containsSaute) {
s"$textはパンフライを記述します。ソースとパンフライの間の類似点は、両方の技法は油でホットパンで食べ物を調理することである。違いは、パンフライングは通常、長い期間中火で大きな部分の食品を調理する必要があり、ソテーリングは高火で小さな部分の食品を迅速に調理する必要があるということです。
} else {
「このテキストは、ソーテージやパンフライのどちらも記述していません。
