```python
def parse_kv_lines(text: str) -> dict:
    """Parse lines of the form 'key=value' into a dictionary.

    Blank lines are ignored. Keys and values are stripped of surrounding whitespace.
    Lines without '=' raise ValueError.

    Examples:
        >>> parse_kv_lines('a=1\nb = 2\n\nc=hello world')
        {'a': '1', 'b': '2', 'c': 'hello world'}
        >>> parse_kv_lines('')
        {}
    """
    result = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        if '=' not in line:
            raise ValueError(f"Line without '=': {line!r}")
        key, value = line.split('=', 1)
        result[key.strip()] = value.strip()
    return result
```

