private static final String[] CONSONANTS = {"b","c","d","f","g","h","j","k","l","m","n","p","q","r","s","t","v","w","x","y","z"};
private static final Map VOWEL_WEIGHTS = new HashMap<>();
static {
VOWEL_WEIGHTS.put("aaa",1);
VOWEL_WEIGHTS.put("aai",2);
VOWEL_WEIGHTS.put("aei",3);
VOWEL_WEIGHTS.put("aoi",2);
