      return n%10 + recursiveSum(n/10);
   }
}

// Iterative function to find sum of digits
int iterativeSum(int n) {
   int sum = 0;
   while(n != 0) {
      sum += abs(n%10);
      n /= 10;
   }
   return sum;
}

int main() {
   int n, sum1, sum2;
   cout << "Enter a positive integer: ";

   while (! (cin >> n) || n < 0) { // validate input
      cin.clear();
      cin.ignore(numeric_limits<streamsize>::max(), '\n');
      cout << "Invalid input. Please enter a positive integer: ";
   }

   sum1 = recursiveSum(n);
   sum2 = iterativeSum(n);

   cout << "Sum using recursion: " << sum1 << endl;
   cout << "Sum using iteration: " << sum2 << endl;

   return 0;
}
```

