``` let article = " CRISPR-Cas9 イノベーションは、遺伝子材料の正確な改変を容易にし、科学者がDNAを比類のない精度と効率で変更することを可能にしました。この技術は、病気の治癒、農業の強化など、幅広い用途を可能にしています。
let verbs = ["facilitated","permitting","alter"]
var verbCount = [String:Int]()
for verb in verbs {
let count = article.components(separatedBy:" ").filter({ $0 == verb }).count
verbCount[verb] = count
}
let sortedVerbs = verbCount.sorted { $0.1 > $1.1 }
let topVerbs = sortedVerbs.prefix(3)
for (verb,count) in topVerbs {
print("(verb) appears (count) times.")
}
