Sure! Here is the updated code that calculates both the area and perimeter of the trapezoid:

% This program prompts the user for the length of the two parallel sides
% and the height of a trapezoid, calculates and displays its area and perimeter.
% The area is calculated using the formula A = (b1 + b2) * h / 2
% and the perimeter is calculated using the formula P = b1 + b2 + 2*sqrt(h^2 + ((b2 - b1)/2)^2).

% Prompting the user for the lengths and height of the trapezoid
b1 = input('Enter the length of the first parallel side: ');
b2 = input('Enter the length of the second parallel side: ');
h = input('Enter the height of the trapezoid: ');

% Checking for negative or zero inputs
if (b1 <= 0) || (b2 <= 0) || (h <= 0)
    disp('Error: Lengths and height must be positive values.')
else
    % Calculating the area and perimeter of the trapezoid
    A = (b1 + b2) * h / 2;
    P = b1 + b2 + 2*sqrt(h^2 + ((b2 - b1)/2)^2);

    % Displaying the area and perimeter of the trapezoid with two decimal places
    fprintf('The area of the trapezoid is %.2f units squared.\n', A)
    fprintf('The perimeter of the trapezoid is %.2f units.\n', P)
end

