using namespace std;

bool isPalindrome(string str)
{
    // Convert string to lowercase
    transform(str.begin(), str.end(), str.begin(), ::tolower);

    // Remove all non-alphanumeric characters
    regex reg("[^a-zA-Z0-9]");
    str = regex_replace(str, reg, "");

    // Check if string is a palindrome
    string revStr = str;
    reverse(revStr.begin(), revStr.end());
    if (str == revStr) {
        return true;
    }
    return false;
}

int main()
{
    string input;

    while (true) {
        cout << "Enter a string to check for palindrome (enter 'exit' to terminate): ";
        getline(cin, input);

        // Exit program if user inputs 'exit'
        if (input == "exit") {
            break;
        }

        // Check if input string is a palindrome
        bool isPal = isPalindrome(input);
        if (isPal) {
            cout << "Valid Palindrome." << endl;
        }
        else {
            cout << "Not a Palindrome." << endl;
        }
    }

    return 0;
}

