response:
Sure! Here's the updated program with more comments:

```
program InvestmentCalculator;
var
  principal, interest_rate: real;
  num_years, iterations: integer;
  total: real;
begin
  // Prompt user for inputs
  writeln('Please enter the initial investment principal: ');
  readln(principal);
  writeln('Please enter the annual interest rate (as a decimal): ');
  readln(interest_rate);
  writeln('Please enter the number of years to invest: ');
  readln(num_years);
  writeln('Please enter the number of times per year interest is compounded (e.g. Monthly = 12, quarterly = 4): ');
  readln(iterations);

  // Calculate total investment by multiplying the principal by the interest rate + 1 
  // raised to the power of how many times per year interest is compounded multiplied by the number of years invested 
  // This is done using a for loop that runs num_years * iterations times
  total := principal;  
  for var I := 1 to num_years * iterations do
  begin
    total := total * (1 + (interest_rate / iterations));
  end;

  // Output the result
  writeln('After ', num_years, ' years, your investment will be worth $', total:0:2);
end.
```

