```python
def parse_config(text: str) -> dict:
    """Parse a small INI-like config format into a nested dict.

    Lines are of the form 'section.key = value' or 'key = value'
    (top-level keys go under ''). Blank lines and lines starting with
    '#' are ignored. Values are stripped; integer-looking values become ints.

    >>> parse_config("a = 1\n# c\n[s]\nb = x\n")
    {'': {'a': 1}, 's': {'b': 'x'}}
    >>> parse_config("")
    {}
    """
    result = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            continue
        key_part, value_part = line.split('=', 1)
        key_part = key_part.strip()
        value_part = value_part.strip()
        if '.' in key_part:
            section, key = key_part.split('.', 1)
            section = section.strip()
            key = key.strip()
        else:
            section, key = '', key_part
        try:
            value = int(value_part)
        except ValueError:
            value = value_part
        result.setdefault(section, {})[key] = value
    return result
```

