```go
package main

import (
    "fmt"
)

// Binary search function that takes an array and a key as input and returns the index of the key in the array, or -1 if not found
func binarySearch(arr []int, key int) int {
    low := 0                  // Index of the first element in the array
    high := len(arr) - 1      // Index of the last element in the array

    for low <= high {         // While there are still elements to search in the array
        mid := (low + high) / 2   // Find the middle index

        if arr[mid] == key {    // If the middle element is the key
            return mid              // Return the index of the middle element
        } else if arr[mid] > key {  // If the middle element is greater than the key
            high = mid - 1             // Discard the right half of the array and search the left half
        } else {                    // If the middle element is less than the key
            low = mid + 1              // Discard the left half of the array and search the right half
        }
    }

    return -1   // If the key is not found in the array, return -1
}

func main() {
    arr := []int{1, 4, 5, 8, 11, 15, 19}   // Array of integers
    var key int                            // Key to be searched for

    fmt.Println("Enter the number to be searched:")
    _, err := fmt.Scanf("%d", &key)

    if err != nil {
        fmt.Println("Invalid input")
        return
    }

    index := binarySearch(arr, key)   // Call the binary search function to search for the key in the array

    if index == -1 {
        fmt.Println(key, "not found in the array")
    } else {
        fmt.Println(key, "found at index", index)
    }
}
