Assistant: ```java
import java.util.Scanner;

public class SumOfIntegers {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int num;
        int sum = 0;
        do {
            System.out.print("Enter a positive integer: ");
            while (!scanner.hasNextInt()) {
                System.out.println("That's not a positive integer! Enter a positive integer: ");
                scanner.next();
            }
            num = scanner.nextInt();
        } while (num < 1);

        for (int I = 1; I <= num; i++) {
            sum += i;
        }
        System.out.println("The sum of all positive integers from 1 to " + num + " is " + sum);
    }
}
```

