# This Perl script extracts data fields from an XML file and converts them into CSV format. 

use strict;
use warnings;
use XML::LibXML;
use Text::CSV;

# open and parse the XML file
my $xml_file = "example.xml";
my $parser = XML::LibXML->new();
my $dom = $parser->parse_file($xml_file);

# create and configure the CSV object
my $csv = Text::CSV->new({
  binary => 1,
  auto_diag => 1,
  eol => "\r\n"
});

# create an array to hold the headers for the CSV file
my @headers = qw(Name Age Gender);

# create the CSV file and add headers
my $csv_file = "output.csv";
open(my $fh, ">", $csv_file) or die "Could not open CSV file: $!";
$csv->print($fh, \@headers);

# iterate through the XML nodes and extract data fields
foreach my $person ($dom->findnodes('/people/person')) {
  my $name = $person->findvalue('name');
  my $age = $person->findvalue('age');
  my $gender = $person->findvalue('gender');

  # construct an array with the extracted data fields
  my @row = ($name, $age, $gender);

  # add the row to the CSV file
  $csv->print($fh, \@row);
}

# close the CSV file
close($fh);

# print a success message
print "CSV file successfully created!\n";

__END__

=head1 NAME

extract_xml.pl - Extracts data fields from an XML file and converts them into CSV format

=head1 SYNOPSIS

    perl extract_xml.pl

=head1 DESCRIPTION

This script extracts specific data fields from an XML file and converts them into comma-separated values (CSV) format. The CSV file includes headers and delimiters that are easy to read and parse by other applications.

=head1 OPTIONS

This script does not accept any options or arguments.

=head1 EXAMPLES

To run the script, simply execute the following command:

    perl extract_xml.pl

This will create a CSV file with the name "output.csv" in the same directory as the script.

=head1 AUTHOR

Written by John Doe.

=cut

