// Java program for bubble sort to sort an array of strings in alphabetical order

import java.util.Scanner;

public class BubbleSortStrings {

    public static void main(String[] args) {

      // Taking input array size from user
      Scanner sc = new Scanner(System.in);      
      System.out.print("Enter the size of array: ");

      // Validating user input using error handling technique
      int size;
      try {
        size = sc.nextInt();
      } catch (Exception e) {
        System.out.println("Invalid input! Please enter a numeric value.");
        return;
      }

      // Validating input for minimum array size
      if (size < 2) {
        System.out.println("Invalid size! Array size cannot be less than 2.");
        return;
      }

      String[] arr = new String[size];

      // Taking input array elements from user
      for(int i=0;i<size;i++) {
        System.out.print("Enter the string at index " + I + ": ");
        arr[i] = sc.next().toLowerCase();
      }

      // Sorting the array of strings using bubble sort
      for(int i=0;i<size-1;i++) {
        for(int j=0;j<size-i-1;j++) {
          if(arr[j].compareTo(arr[j+1]) > 0) {
            String temp = arr[j];
            arr[j] = arr[j+1];      
            arr[j+1] = temp;
          }
        }
      }

      // Printing sorted array elements
      System.out.println("\nThe sorted array of strings is: ");
      for(int i=0;i<size;i++) {
        System.out.print(arr[i] + " ");
      }

    }
} 

