#include <iostream>

int main() {
    int start, end;
    std::cout << "Enter the starting integer: ";
    if (!(std::cin >> start)) {
        std::cout << "Invalid input, exiting.\n";
        return 1;
    }
    std::cout << "Enter the ending integer: ";
    if (!(std::cin >> end)) {
        std::cout << "Invalid input, exiting.\n";
        return 1;
    }
    int sum = 0;
    for (int I = start; I <= end; ++i) {
        if (i % 2 == 0) {
            sum += i;
        }
    }
    std::cout << "The sum of all even numbers between " << start
              << " and " << end << " is " << sum << ".\n";
    return 0;
}

