def triangle_area_and_perimeter(a: float, b: float, c: float) -> tuple[float, float]:
    """Return the area and perimeter of a triangle given its three side lengths.

    If the sides do not form a valid triangle, return (0.0, 0.0).

    Examples:
        triangle_area_and_perimeter(3, 4, 5) -> (6.0, 12.0)
        triangle_area_and_perimeter(1, 2, 10) -> (0.0, 0.0)
    """
    if a <= 0 or b <= 0 or c <= 0:
        return (0.0, 0.0)
    if a + b <= c or a + c <= b or b + c <= a:
        return (0.0, 0.0)

    perimeter = a + b + c
    s = perimeter / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
    return (area, perimeter)
```

