```python
def max_island_after_flip(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    island_id = [[-1] * cols for _ in range(rows)]
    sizes = {}
    current_id = 0

    def dfs(r, c):
        stack = [(r, c)]
        island_id[r][c] = current_id
        size = 0
        while stack:
            x, y = stack.pop()
            size += 1
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1 and island_id[nx][ny] == -1:
                    island_id[nx][ny] = current_id
                    stack.append((nx, ny))
        return size

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and island_id[r][c] == -1:
                sizes[current_id] = dfs(r, c)
                current_id += 1

    if current_id == 0:
        return 1
    if current_id == 1 and all(grid[r][c] == 1 for r in range(rows) for c in range(cols)):
        return rows * cols

    best = max(sizes.values())

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                neighbor_ids = set()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dx, c + dy
                    if 0 <= nr < rows and 0 <= nc < cols and island_id[nr][nc] != -1:
                        neighbor_ids.add(island_id[nr][nc])
                total = 1 + sum(sizes[i] for i in neighbor_ids)
                best = max(best, total)

    return best
```

