Import java.util.UUID

def generateUUID() {
    String hexDigits = "0123456789abcdef"
    Random random = new Random()

    // Generate the first three groups of hexadecimal digits
    StringBuilder sb = new StringBuilder()
    for (int I = 0; I < 8; i++) {
        sb.append(hexDigits.charAt(random.nextInt(16)))
    }
    sb.append("-")
    for (int I = 0; I < 4; i++) {
        sb.append(hexDigits.charAt(random.nextInt(16)))
    }
    sb.append("-1")
    for (int I = 0; I < 3; i++) {
        sb.append(hexDigits.charAt(random.nextInt(16)))
    }
    sb.append("-")

    // Generate the fourth group of hexadecimal digits with the two most significant bits set to 1 and 0, respectively
    sb.append(hexDigits.charAt((random.nextInt(4) + 8) << 4 | random.nextInt(16)))
    for (int I = 0; I < 3; i++) {
        sb.append(hexDigits.charAt(random.nextInt(16)))
    }
    sb.append("-")

    // Generate the fifth group of hexadecimal digits
    for (int I = 0; I < 12; i++) {
        sb.append(hexDigits.charAt(random.nextInt(16)))
    }

    return UUID.fromString(sb.toString())
}

def uuid = generateUUID()
println(uuid)

