User: Create a PowerShell script that can extract data from a CSV file and filter it based on specific conditions such as date range, numerical values, or text patterns. The script should also have the ability to output filtered data to a new CSV file or display it on the console. Use best practices for naming conventions, code structure, and error handling to ensure readability and maintainability of the script.

Assistant: # Define input parameters
param(
    [string]$csvFilePath,
    [string]$outputFilePath,
    [string]$startDate,
    [string]$endDate,
    [int]$minValue,
    [int]$maxValue,
    [string]$pattern
)

# Import CSV data
$data = Import-Csv -Path $csvFilePath

# Filter data based on start and end date
if($startDate -and $endDate) {
    $data = $data | Where-Object { $_.Date -ge $startDate -and $_.Date -le $endDate }
}

# Filter data based on numerical values
if($minValue -and $maxValue) {
    $data = $data | Where-Object { $_.Value -ge $minValue -and $_.Value -le $maxValue }
}

# Filter data based on text pattern
if($pattern) {
    $data = $data | Where-Object { $_.Description -match $pattern }
}

# Output filtered data to new CSV file or console
if($outputFilePath) {
    $data | Export-Csv -Path $outputFilePath -NoTypeInformation
} else {
    $data
}

# Error handling
if($error) {
    $errorMessage = $error[0].ToString()
    Write-Host "An error occured: $errorMessage" -ForegroundColor Red
} else {
    Write-Host "Data extracted successfully!" -ForegroundColor Green
}

# End of script

