```python
def min_moves_to_collect_all(grid: list[list[int]], start: tuple[int, int]) -> int:
    from collections import deque
    from itertools import permutations

    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    sr, sc = start

    # If start is a wall, impossible
    if grid[sr][sc] == 1:
        return -1

    # Collect item positions
    items = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] >= 2:
                items[grid[r][c]] = (r, c)

    # No items to collect
    if not items:
        return 0

    def bfs(src):
        """BFS from src returning dict of distances to all reachable cells."""
        dist = {src: 0}
        q = deque([src])
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] != 1 and (nr, nc) not in dist:
                        dist[(nr, nc)] = dist[(r, c)] + 1
                        q.append((nr, nc))
        return dist

    # Precompute BFS from start and each item
    points = [start] + list(items.values())
    labels = [None] + list(items.keys())  # None for start
    n = len(points)
    dist_matrix = [[None] * n for _ in range(n)]

    for i in range(n):
        d = bfs(points[i])
        for j in range(n):
            dist_matrix[i][j] = d.get(points[j], None)

    # Check reachability
    for j in range(1, n):
        if dist_matrix[0][j] is None:
            return -1

    # Try all permutations of item collection order
    best = float('inf')
    item_indices = list(range(1, n))
    for perm in permutations(item_indices):
        total = 0
        cur = 0
        ok = True
        for idx in perm:
            if dist_matrix[cur][idx] is None:
                ok = False
                break
            total += dist_matrix[cur][idx]
            cur = idx
        if ok:
            best = min(best, total)

    return best if best != float('inf') else -1
```

