```c++
#include <iostream>
using namespace std;

/**
 * Recursive binary search algorithm to search for a target element in a sorted array of integers.
 * 
 * @param arr the sorted array to search in
 * @param low the starting index of the sub-array to search in
 * @param high the ending index of the sub-array to search in
 * @param target the target element to search for
 * @param numCalls reference to the number of recursive calls made during the algorithm
 * 
 * @return the index of the target element if found, or -1 if not found
 */
int binarySearch(int arr[], int low, int high, int target, int &numCalls) {
    if (low > high) {
        // element not found, base case of the recursion
        numCalls++;
        return -1;
    }

    // calculate the middle index of the sub-array
    int mid = low + (high - low) / 2;

    if (arr[mid] == target) {
        // target found, base case of the recursion
        numCalls++;
        return mid;
    }
    else if (arr[mid] > target) {
        // target is in the left half of the sub-array
        numCalls++;
        return binarySearch(arr, low, mid - 1, target, ++numCalls);
    }
    else {
        // target is in the right half of the sub-array
        numCalls++;
        return binarySearch(arr, mid + 1, high, target, ++numCalls);
    }
}

int main() {
    int size, target;
    cout << "Enter size of array: ";
    cin >> size;

    int arr[size];
    cout << "Enter elements of array in sorted order:\n";
    for (int I = 0; I < size; i++) {
        cin >> arr[i];
    }

    cout << "Enter target element to search for: ";
    cin >> target;

    int numCalls = 0;
    int result = binarySearch(arr, 0, size - 1, target, numCalls);
    if (result != -1) {
        cout << "Target element found at index " << result << " after " << numCalls << " recursive calls.\n";
    }
    else {
        cout << "Target element not found after " << numCalls << " recursive calls.\n";
    }

    return 0;
}
