```python
def parse_kv_lines(text: str) -> dict:
    """Parse a small text format of 'key=value' lines into a dict.

    Lines are stripped; blank lines and lines starting with '#' are ignored.
    Each remaining line must contain exactly one '='. Keys and values are
    stripped of surrounding whitespace. Later duplicate keys overwrite earlier ones.

    Examples:
        parse_kv_lines('a=1\nb = 2\n') == {'a': '1', 'b': '2'}
        parse_kv_lines('# c\nx=y=z\n') == {'x': 'y=z'}
    """
    result = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Line missing '=': {raw_line!r}")
        key, value = line.split('=', 1)
        result[key.strip()] = value.strip()
    return result
```

