``` // ガーデンサプライリストの各アイテムの構造を定義する
struct GardenSupplyItem {
var name:String
var category:String
var購入:ボール
} // 庭の供給アイテムを保持する配列を定義する
var gardenSupplies = [
GardenSupplyItem(名前:"ショベル",カテゴリ:"掘削/植え付け",購入:偽),
GardenSupplyItem(名前:"コンポスト",カテゴリー:"土",購入:偽),
