GardenSupplyItem(名前:"殺菌剤",カテゴリ:"消化管理",購入:偽物),
GardenSupplyItem(名前:"Grow Light",カテゴリ:"Lighting",購入:false)
] // 庭の供給リストに新しい項目を追加する機能を定義する
func addGardenSupplyItem(name:String,category:String,purchased:Bool) {
let newItem = GardenSupplyItem(name:name,category:category,purchased:purchased)
gardenSupplies.append(newItem)
} // ガーデンサプライリスト内の既存アイテムを編集する機能を定義する
func editGardenSupplyItem(index:Int,name:String,category:String,purchased:Bool) {
gardenSupplies[index].name = 名前
gardenSupplies[index].category = カテゴリー
gardenSupplies[index].purchased = purchased
} // ガーデンの供給リストから項目を削除する機能を定義する
func deleteGardenSupplyItem(index:Int) {
gardenSupplies.remove(at:index)
} // 庭の供給リスト内の特定の項目を検索する機能を定義する
func searchGardenSupplies(query:String) -> [GardenSupplyItem] {
let results = gardenSupplies.filter { $0.name.lowercased().contains(query.lowercased()) }
結果を返す
} ``` このコードは、ガーデンサプライリスト内の各アイテムの名前、カテゴリ、および購入されたステータスを保持する`GardenSupplyItem` 構造を定義します。また、項目を保持する「gardenSupplies」と呼ばれる配列を定義し、配列から項目を追加、編集、削除する機能、ユーザのクエリに基づいて項目を検索する機能を定義します。
