```javascript
const sideA = 5;
const sideB = 7;
const angleC = 60;
// 欠けている値を計算する
const sideC = Math.sqrt(sideA ** 2 + sideB ** 2 - 2 * sideA * sideB * Math.cos(angleC * Math.PI / 180));
const angleA = Math.asin(sideA * Math.sin(angleC * Math.PI / 180) / sideC) * 180 / Math.PI;
const angleB = 180 - angleA - angleC;
// 結果を表示
console.log(`Side A:${sideA}`);
console.log(`Side B:${sideB}`);
console.log(`Side C:${sideC}`);
console.log(`Angle A:${angleA}`);
console.log(`Angle B:${angleB}`);
console.log(`Angle C:${angleC}`);
// 三角形を描く
const canvas = document.getElementById('canvas');
const context = canvas.getContext('2d');
context.beginPath();
context.moveTo(50,50);
context.lineTo(50 + sideA * 10,50);
context.lineTo(50 + sideB * 10 * Math.cos(angleC * Math.PI / 180),50 + sideB * 10 * Math.sin(angleC * Math.PI / 180));
context.closePath();
context.stroke();
