``` php
header("Content-Type:image/png");
$im = imagecreatefrompng('logo.png');
imagealphablending($im,true);
imagesavealpha($im,true);
$shadow = imagecreatetruecolor(imagesx($im),imagesy($im));
$shadow_color = imagecolorallocatealpha($shadow,0,0,0,100);
imagefill($shadow,0,0,$shadow_color);
imagecopy($shadow,$im,1,1,0,0,imagesx($im),imagesy($im));
imagecopy($shadow,$im,0,0,0,0,imagesx($im),imagesy($im));
imagecopy($shadow,$im,-1,-1,0,0,imagesx($im),imagesy($im));
imagecopy($shadow,$im,0,-1,0,0,imagesx($im),imagesy($im));
imagecopy($shadow,$im,-1,0,0,0,imagesx($im),imagesy($im));
imagefilter($shadow,IMG_FILTER_GAUSSIAN_BLUR);
imagecopymerge($im,$shadow,0,0,0,0,imagesx($im),imagesy($im),50);
imagepng($im);
imagedestroy($im);
imagedestroy($shadow); ?
